// ═══════════════════════════════════════════════════════════════════════════════
// LOOKUP FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════════════

/** Get scraper by ID */
export function getScraperById(id: string): GoMarketplaceItem | undefined {
  return GO_SCRAPERS.find(s => s.id === id);
}

/** Get scrapers by category */
export function getScrapersByCategory(category: string): GoMarketplaceItem[] {
  return GO_SCRAPERS.filter(s => s.category === category);
}

/** Get workflow by ID */
export function getWorkflowById(id: string): GoWorkflow | undefined {
  return GO_WORKFLOWS.find(w => w.id === id);
}

/** Get workflows by type */
export function getWorkflowsByType(type: string): GoWorkflow[] {
  return GO_WORKFLOWS.filter(w => w.type === type);
}
